//! 🧪️ The actual grammar retains accepted source, native cause and output under one finite original caller until complete paid closure.
use super::*;
use semio_framework_job::{OriginalJobFixtureCaller,OperationId,Generation};
use semio_framework_value::{RetainedCloneGrant, RetainedCloneProgress, RetireOwned};
use semio_framework_value_native_owned::native_decoding::NativeDecodeContinuation;
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
fn clock()->Option<u64>{Some(1000)}
fn delta(before:RetainedCloneProgress,after:RetainedCloneProgress)->RetainedCloneProgress{RetainedCloneProgress{copied_items:after.copied_items-before.copied_items,copied_bytes:after.copied_bytes-before.copied_bytes,retained_capacity_bytes:after.retained_capacity_bytes-before.retained_capacity_bytes,released_bytes:after.released_bytes-before.released_bytes}}
fn close<T:RetireOwned>(owner:&mut ControlledRetirement<T>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if owner.terminal_is_empty(){return Ok(true)}let demand=owner.selected_demand(cx.retained_grant().maximum_copy_bytes)?;let _=semio_framework_job::close_original_retained_step(cx,demand,|grant|owner.step(grant))?;Ok(owner.terminal_is_empty())}
#[test]
fn original_presented_params_same_source_native_cause_denials_and_full_paid_close(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../../../../../🧪️tests/🧫️fixtures/🧊️wgpu/🎬️media-slots/📥️props/🔣️.json")).unwrap();let policy:serde_json::Value=serde_json::from_str(include_str!("../../../../../../../🔌️plugin/🧪️testing/🎟️caller/🧪️tests/🧫️fixtures/🎟️caller.json")).unwrap();let stock:RetainedCloneGrant=serde_json::from_value(policy["grant"].clone()).unwrap();
 for copy in [1,3,64]{for row in law["cases"].as_array().unwrap(){for cut in [0usize,1,13,64,usize::MAX]{
  let source=row["source"].as_str().unwrap();let pointer=source.as_ptr();let(mut caller,bootstrap)=observe(||OriginalJobFixtureCaller::admit(OperationId(policy["operation"].as_u64().unwrap()),Generation(policy["generation"].as_u64().unwrap()),stock,clock,policy["deadlineUs"].as_u64().unwrap(),policy["fuel"].as_u64().unwrap()));let mut born=bootstrap.requested_bytes;let mut freed=bootstrap.released_bytes;
  caller.turn(stock,|cx|{let identity=(cx.operation(),cx.generation(),cx.clock_source()as usize,cx.deadline_us(),cx.original_recipient_identity());let limits=JsonReadLimits{maximum_bytes:super::super::PRESENTED_MEDIA_DESCRIPTOR_BYTES as u64,maximum_allocation_bytes:stock.maximum_capacity_bytes,maximum_depth:stock.maximum_depth,maximum_items:stock.maximum_items as u64};let mut parser=OriginalPresentedParams::admit(source,limits,cx).map_err(|error|match error{PresentedParamsStepFailure::Original(error)=>error,_=>panic!("empty grammar admission must preserve native source")})?.unwrap();let mut output=None;let mut failure=None;let mut native:Option<NativeDecodeContinuation>=None;
   for turn in 0..cut{let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy.min(cx.retained_grant().maximum_copy_bytes),..cx.retained_grant()};let demand=parser.parser.original().unwrap().normal_step_demands(source);if let Ok(demand)=demand{for axis in 0..5{let extent=match axis{0=>1,1=>demand.copy_bytes,2=>demand.capacity_bytes,3=>demand.release_bytes,_=>demand.depth};if extent==0{continue}let mut denied=grant;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=extent-1,2=>denied.maximum_capacity_bytes=extent-1,3=>denied.maximum_release_bytes=extent-1,_=>denied.maximum_depth=extent-1};let before=cx.retained_progress();let fuel=cx.fuel_remaining();let(_,heap)=observe(||cx.with_retained_loan(denied,|same|{let cancel=same.borrowed_original_cancel_token()?;let clock=same.clock_source();let deadline=same.deadline_us();let mut accepted=|_|!cancel.is_cancelled_now()&&clock().is_some_and(|now|now<deadline);let mut control=match native.take(){Some(saved)=>NativeDecodeControl::resume(saved,&mut accepted)?,None=>NativeDecodeControl::new_retained(&mut accepted)};assert!(!parser.advance(source,&mut output,&mut control,same).unwrap());native=Some(control.pause()?);Ok(())}));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(before,cx.retained_progress());assert_eq!(fuel,cx.fuel_remaining())}}
    let before=cx.retained_progress();let(result,heap)=observe(||cx.with_retained_loan(grant,|same|{let cancel=same.borrowed_original_cancel_token()?;let clock=same.clock_source();let deadline=same.deadline_us();let mut accepted=|_|!cancel.is_cancelled_now()&&clock().is_some_and(|now|now<deadline);let mut control=match native.take(){Some(saved)=>NativeDecodeControl::resume(saved,&mut accepted)?,None=>NativeDecodeControl::new_retained(&mut accepted)};let result=parser.advance(source,&mut output,&mut control,same);native=Some(control.pause()?);Ok(result)}));let progress=delta(before,cx.retained_progress());assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));born+=heap.requested_bytes;freed+=heap.released_bytes;assert_eq!(source.as_ptr(),pointer);assert_eq!((cx.operation(),cx.generation(),cx.clock_source()as usize,cx.deadline_us(),cx.original_recipient_identity()),identity);match result?{Ok(true)=>break,Ok(false)=>{},Err(original)=>{if let PresentedParamsStepFailure::Grammar(cause)=&original{assert_eq!(json_kind(&cause.cause),row["cause"].as_str().unwrap());if let JsonError::DuplicateMember{name,..}=&cause.cause{assert_eq!(name,row["member"].as_str().unwrap());assert!(matches!(cause.projection_view(&[0,4])?,V::IntrinsicText(text)if text.as_ptr()==name.as_ptr()))}}failure=Some(original);break}}assert!(turn<100000)}
   if cut==usize::MAX&&row["result"]=="ready"{let reference:serde_json::Value=serde_json::from_str(source).unwrap();assert_eq!(serde_json::to_value(output.as_ref().unwrap()).unwrap(),reference);assert_eq!(output.as_ref().unwrap().get("revision").unwrap().as_u64(),Some(u64::MAX));}if cut!=usize::MAX{let grant=cx.retained_grant();let progress=cx.borrowed_original_cancel_token()?.signal_cancelled_flag_step(grant).unwrap();cx.consume_retained(progress)?;cx.consume_fuel(1);}
   while !parser.terminal_is_empty(){let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy.min(cx.retained_grant().maximum_copy_bytes),..cx.retained_grant()};let before=cx.retained_progress();let(result,heap)=observe(||cx.with_retained_loan(grant,|same|parser.close_step(same)));result?;let progress=delta(before,cx.retained_progress());assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));born+=heap.requested_bytes;freed+=heap.released_bytes;assert!(!cx.fuel_exhausted())}assert_eq!(observe(||drop(parser)).1.requested_bytes,0);
   let mut owners=ControlledRetirement::new((output,failure)).unwrap_or_else(|_|unreachable!());while !owners.terminal_is_empty(){let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy.min(cx.retained_grant().maximum_copy_bytes),..cx.retained_grant()};let before=cx.retained_progress();let(result,heap)=observe(||cx.with_retained_loan(grant,|same|close(&mut owners,same)));result?;let progress=delta(before,cx.retained_progress());assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));born+=heap.requested_bytes;freed+=heap.released_bytes;assert!(!cx.fuel_exhausted())}assert_eq!(observe(||drop(owners)).1.released_bytes,0);drop(native);Ok(())}).unwrap();let(_,heap)=observe(||caller.retire(stock));born+=heap.requested_bytes;freed+=heap.released_bytes;assert_eq!(born,freed);
 }}}
}
